package io.music_assistant.sendspin.api

import co.touchlab.kermit.Logger

/**
 * Recreates a stateful platform decoder once per configured stream after an
 * invalid-state error. All calls belong to the audio thread. No network retry,
 * queue change, or user Play is generated by codec recovery.
 */
class RecoveringAudioDecoder(private val create: () -> AudioDecoder) : AudioDecoder {
    private val log = Logger.withTag("RecoveringAudioDecoder")
    private var current: AudioDecoder? = null
    private var format: AudioFormatSpec? = null
    private var header: ByteArray? = null
    private var recoveryUsed = false

    override val outputBitDepth: Int get() = current?.outputBitDepth ?: format?.bitDepth ?: 16
    override val outputCodec: AudioCodec get() = current?.outputCodec ?: AudioCodec.PCM

    override fun configure(format: AudioFormatSpec, codecHeader: ByteArray?) {
        release()
        this.format = format
        header = codecHeader?.copyOf()
        recoveryUsed = false
        open()
    }

    private fun open() {
        val spec = checkNotNull(format)
        val next = create()
        try {
            next.configure(spec, header?.copyOf())
            current = next
        } catch (e: Exception) {
            runCatching { next.release() }
            throw e
        }
    }

    private fun discard() {
        val previous = current
        current = null
        runCatching { previous?.release() }
    }

    private fun recover(): Boolean {
        discard()
        if (format == null || recoveryUsed) return false
        recoveryUsed = true
        return try {
            open()
            log.i { "Platform decoder recreated once for ${format?.codec}" }
            true
        } catch (e: Exception) {
            log.w { "Platform decoder recreation failed: ${e::class.simpleName}" }
            false
        }
    }

    override fun decode(input: ByteArray, offset: Int, length: Int): ByteArray {
        val active = current ?: return ByteArray(0)
        return try {
            active.decode(input, offset, length)
        } catch (e: IllegalStateException) {
            if (!recover()) return ByteArray(0)
            try {
                checkNotNull(current).decode(input, offset, length)
            } catch (retry: IllegalStateException) {
                discard()
                ByteArray(0)
            }
        }
    }

    override fun reset() {
        try {
            current?.reset()
        } catch (e: IllegalStateException) {
            recover()
        }
    }

    override fun release() {
        discard()
        format = null
        header = null
        recoveryUsed = true
    }
}
